mapper.select:
SELECT * FROM post
WHERE community_id = #{communityId}

    AND (created_at < #{lastCreateTime}
         OR (created_at = #{lastCreateTime} AND id < #{lastId}))

ORDER BY created_at DESC, id DESC
LIMIT #{pageSize}

SELECT id, community_id, author_id, title, content, latitude, longitude, geohash,
       created_at AS create_time, updated_at AS update_time
FROM post
WHERE geohash >= #{geohashStart}
  AND geohash < #{geohashEnd}

    AND (created_at < #{lastCreateTime}
         OR (created_at = #{lastCreateTime} AND id < #{lastId}))

ORDER BY created_at DESC, id DESC
LIMIT #{pageSize}

mapper.update:
UPDATE post
SET title = #{title}, content = #{content}
WHERE id = #{id} AND author_id = #{authorId}

UPDATE post
SET like_count = like_count + #{count}
WHERE id = #{id}

UPDATE post
SET favorite_count = favorite_count + #{count}
WHERE id = #{id}

UPDATE post
SET comment_count = comment_count + 1
WHERE id = #{id}

mapper.select:
SELECT c.id, c.content, c.author_id AS user_id, u.nickname, c.created_at AS create_time
FROM comment c
LEFT JOIN `user` u ON u.id = c.author_id
WHERE c.post_id = #{postId}

    AND (c.created_at < #{lastCreateTime}
         OR (c.created_at = #{lastCreateTime} AND c.id < #{lastId}))

ORDER BY c.created_at DESC, c.id DESC
LIMIT #{pageSize}
